/**
 * Journey chrome models — pure functions behind the Home shelf, the Journeys
 * sheet, the trip panel copy and the `#/trip/<id>` deep links.
 *
 * Nothing here touches the map. The legacy runtime (`legacy/diary-app.js`)
 * mounts the rendered HTML and wires clicks to `selectTrip` / `startPlayback`.
 */
import type { Trip, TripPhoto } from "../types";
import { isJourneyTrip } from "../journey-filter";

export interface JourneyCard {
  id: string;
  /** "Dec 2025" */
  kicker: string;
  /** "Bellevue → Redondo Beach" */
  title: string;
  /** "via WA, OR, ID, NV, UT, AZ, CA" or "" */
  via: string;
  /** "4,592 mi · 20 days · 79 memories" — or "… · Path only" */
  meta: string;
  memories: number;
  miles: number;
  days: number;
  /** First photo thumb (relative or CDN URL) — null for path-only trips. */
  cover: string | null;
  color: string;
  featured: boolean;
  /** Multi-day journey (shelf + list) vs. a short mapped drive (list only). */
  isJourney: boolean;
  start: string;
  year: string;
  /** Inline SVG of the overview polyline — every card shows the shape of the road. */
  sketch: string;
}

const MONTHS = ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"];

export function escapeHtml(s: unknown): string {
  return String(s ?? "")
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;")
    .replace(/'/g, "&#39;");
}

export function tripKicker(trip: Pick<Trip, "name" | "start">): string {
  const fromName = String(trip.name || "").split("—")[0]?.trim();
  if (fromName && /\b(19|20)\d{2}\b/.test(fromName) && fromName.length <= 12) return fromName;
  const start = String(trip.start || "");
  const m = /^(\d{4})-(\d{2})/.exec(start);
  if (!m) return fromName || "";
  const month = MONTHS[Number(m[2]) - 1] || "";
  return `${month} ${m[1]}`.trim();
}

/**
 * "Dec 2025 — Bellevue → Redondo Beach (via WA, …) · Rama + Akash (Akash's car)"
 * → "Bellevue → Redondo Beach". Prefers the structured origin/destination labels.
 */
export function tripTitle(trip: Pick<Trip, "name" | "origin_label" | "story_dest" | "dest_label">): string {
  const origin = String(trip.origin_label || "").trim();
  const dest = String(trip.story_dest || "").trim();
  if (origin && dest && origin !== dest) return `${origin} → ${dest}`;
  let rest = String(trip.name || "");
  const dash = rest.indexOf("—");
  if (dash >= 0) rest = rest.slice(dash + 1);
  rest = rest.replace(/\s*\((?:via|through)[^)]*\)/i, "");
  // " · 2" counters and " · Rama + Akash (Akash's car)" crew suffixes are metadata, not the title.
  const dot = rest.indexOf("·");
  if (dot >= 0) rest = rest.slice(0, dot);
  rest = rest.trim();
  if (rest) return rest;
  return dest || String(trip.dest_label || "") || String(trip.name || "");
}

export function tripVia(trip: Pick<Trip, "via_summary" | "states">): string {
  const via = String(trip.via_summary || "").trim();
  if (via) return `via ${via}`;
  const states = Array.isArray(trip.states) ? trip.states.map(String) : [];
  return states.length > 1 ? `via ${states.join(", ")}` : "";
}

export function tripMemoryCount(trip: Pick<Trip, "photos">): number {
  const photos: TripPhoto[] = Array.isArray(trip.photos) ? trip.photos : [];
  return photos.filter((p) => p && p.thumb).length;
}

export function tripCover(trip: Pick<Trip, "photos">): string | null {
  const photos: TripPhoto[] = Array.isArray(trip.photos) ? trip.photos : [];
  const withThumb = photos.filter((p) => p && p.thumb);
  if (!withThumb.length) return null;
  // Middle of the trip reads as "the destination" more often than the first shot in the driveway.
  const pick = withThumb[Math.floor(withThumb.length / 2)] || withThumb[0];
  return pick.thumb || null;
}

export function tripMeta(trip: Trip): string {
  const miles = Number(trip.miles) || 0;
  const days = Number(trip.duration_days) || 0;
  const memories = tripMemoryCount(trip);
  const parts = [
    miles ? `${miles.toLocaleString()} mi` : "",
    days ? `${days} day${days === 1 ? "" : "s"}` : "",
    memories ? `${memories} memor${memories === 1 ? "y" : "ies"}` : "Path only",
  ].filter(Boolean);
  return parts.join(" · ");
}

/**
 * Minimal SVG of the overview polyline (`[lat, lng]` pairs), aspect-correct
 * (cos-lat scaled) and padded, as a string ready for `innerHTML`.
 */
export function routeSketchSvg(
  path: ReadonlyArray<readonly [number, number]> | undefined,
  color: string,
  width = 240,
  height = 120,
  maxPoints = 180,
): string {
  const pts = Array.isArray(path) ? path.filter((p) => Array.isArray(p) && Number.isFinite(p[0]) && Number.isFinite(p[1])) : [];
  if (pts.length < 2) {
    return `<svg class="route-sketch" viewBox="0 0 ${width} ${height}" aria-hidden="true"></svg>`;
  }
  const stride = Math.max(1, Math.ceil(pts.length / maxPoints));
  const sampled: Array<readonly [number, number]> = [];
  for (let i = 0; i < pts.length; i += stride) sampled.push(pts[i]);
  if (sampled[sampled.length - 1] !== pts[pts.length - 1]) sampled.push(pts[pts.length - 1]);

  let minLat = Infinity, maxLat = -Infinity, minLng = Infinity, maxLng = -Infinity;
  for (const [lat, lng] of sampled) {
    if (lat < minLat) minLat = lat;
    if (lat > maxLat) maxLat = lat;
    if (lng < minLng) minLng = lng;
    if (lng > maxLng) maxLng = lng;
  }
  const midLat = (minLat + maxLat) / 2;
  const kx = Math.cos((midLat * Math.PI) / 180) || 1;
  const spanX = Math.max((maxLng - minLng) * kx, 1e-6);
  const spanY = Math.max(maxLat - minLat, 1e-6);
  const pad = 10;
  const scale = Math.min((width - pad * 2) / spanX, (height - pad * 2) / spanY);
  const drawW = spanX * scale;
  const drawH = spanY * scale;
  const ox = (width - drawW) / 2;
  const oy = (height - drawH) / 2;
  const fmt = (n: number) => (Math.round(n * 10) / 10).toString();
  const d = sampled
    .map(([lat, lng], i) => {
      const x = ox + (lng - minLng) * kx * scale;
      const y = oy + (maxLat - lat) * scale;
      return `${i === 0 ? "M" : "L"}${fmt(x)} ${fmt(y)}`;
    })
    .join("");
  const [sLat, sLng] = sampled[0];
  const [eLat, eLng] = sampled[sampled.length - 1];
  const sx = ox + (sLng - minLng) * kx * scale, sy = oy + (maxLat - sLat) * scale;
  const ex = ox + (eLng - minLng) * kx * scale, ey = oy + (maxLat - eLat) * scale;
  const safe = escapeHtml(color || "#ffffff");
  return (
    `<svg class="route-sketch" viewBox="0 0 ${width} ${height}" aria-hidden="true">` +
    `<path d="${d}" fill="none" stroke="${safe}" stroke-opacity="0.28" stroke-width="7" stroke-linejoin="round" stroke-linecap="round"/>` +
    `<path d="${d}" fill="none" stroke="${safe}" stroke-width="2.4" stroke-linejoin="round" stroke-linecap="round"/>` +
    `<circle cx="${fmt(sx)}" cy="${fmt(sy)}" r="3.2" fill="#ffffff" fill-opacity="0.9"/>` +
    `<circle cx="${fmt(ex)}" cy="${fmt(ey)}" r="3.2" fill="${safe}" stroke="#ffffff" stroke-width="1.5"/>` +
    `</svg>`
  );
}

export function journeyCard(trip: Trip): JourneyCard {
  const start = String(trip.start || "");
  return {
    id: trip.id,
    kicker: tripKicker(trip),
    title: tripTitle(trip),
    via: tripVia(trip),
    meta: tripMeta(trip),
    memories: tripMemoryCount(trip),
    miles: Number(trip.miles) || 0,
    days: Number(trip.duration_days) || 0,
    cover: tripCover(trip),
    color: String(trip.color || "#64d2ff"),
    featured: Boolean(trip.featured),
    isJourney: isJourneyTrip(trip),
    start,
    year: start.slice(0, 4),
    sketch: routeSketchSvg(trip.route_overview || trip.route_path, String(trip.color || "#64d2ff")),
  };
}

/** Newest first; multi-day journeys only (the shelf is for films, not errands). */
export function shelfCards(trips: Trip[]): JourneyCard[] {
  return trips
    .filter(isJourneyTrip)
    .sort((a, b) => String(b.start || "").localeCompare(String(a.start || "")))
    .map(journeyCard);
}

export type ThumbResolver = (thumb: string) => string;

function coverHtml(card: JourneyCard, thumbUrl: ThumbResolver, opts: { memBadge?: boolean } = {}): string {
  const cover = card.cover ? thumbUrl(card.cover) : "";
  const photo = cover
    ? `<img class="journey-card-photo" src="${escapeHtml(cover)}" alt="" loading="lazy" decoding="async">`
    : "";
  const mem =
    opts.memBadge && card.memories
      ? `<span class="journey-card-mem" aria-hidden="true">${escapeHtml(String(card.memories))}</span>`
      : "";
  return `<div class="journey-card-art" style="--trip-color:${escapeHtml(card.color)}">${card.sketch}${photo}${mem}</div>`;
}

function metaChipsHtml(card: JourneyCard): string {
  const chips: string[] = [];
  if (card.miles) {
    chips.push(`<span class="meta-chip">${escapeHtml(card.miles.toLocaleString())} mi</span>`);
  }
  if (card.days) {
    chips.push(
      `<span class="meta-chip">${escapeHtml(String(card.days))} day${card.days === 1 ? "" : "s"}</span>`,
    );
  }
  if (card.memories) {
    chips.push(
      `<span class="meta-chip is-memories">${escapeHtml(String(card.memories))} memor${card.memories === 1 ? "y" : "ies"}</span>`,
    );
  } else {
    chips.push(`<span class="meta-chip is-path">Path only</span>`);
  }
  return chips.join("");
}

/** Poster card markup for the Home shelf. */
export function renderShelfCard(card: JourneyCard, thumbUrl: ThumbResolver): string {
  return (
    `<button type="button" class="journey-card${card.memories ? " has-memories" : ""}" role="listitem" data-trip-id="${escapeHtml(card.id)}" ` +
    `aria-label="${escapeHtml(`${card.kicker} — ${card.title}, ${card.meta}`)}" ` +
    `style="--trip-color:${escapeHtml(card.color)}">` +
    coverHtml(card, thumbUrl, { memBadge: true }) +
    `<div class="journey-card-copy">` +
    `<span class="journey-card-kicker">${escapeHtml(card.kicker)}</span>` +
    `<span class="journey-card-title">${escapeHtml(card.title)}</span>` +
    `<span class="journey-card-meta">${metaChipsHtml(card)}</span>` +
    `</div>` +
    `<span class="journey-card-play" aria-hidden="true"><svg viewBox="0 0 24 24" fill="currentColor"><path d="M8 5v14l11-7L8 5z"/></svg></span>` +
    `</button>`
  );
}

export function renderShelf(trips: Trip[], thumbUrl: ThumbResolver): string {
  return shelfCards(trips).map((card) => renderShelfCard(card, thumbUrl)).join("");
}

/** Full list for the Journeys sheet: journeys grouped by year, short drives in one trailing group. */
export function renderJourneyList(trips: Trip[], thumbUrl: ThumbResolver): string {
  const cards = trips
    .slice()
    .sort((a, b) => String(b.start || "").localeCompare(String(a.start || "")))
    .map(journeyCard);
  const journeys = cards.filter((c) => c.isJourney);
  const drives = cards.filter((c) => !c.isJourney);
  const item = (card: JourneyCard) =>
    `<button type="button" class="trip-item journey-row${card.memories ? " has-memories" : ""}" data-id="${escapeHtml(card.id)}" data-year="${escapeHtml(card.year)}" style="--trip-color:${escapeHtml(card.color)}">` +
    coverHtml(card, thumbUrl) +
    `<span class="journey-row-copy">` +
    `<span class="journey-row-kicker">${escapeHtml(card.kicker)}</span>` +
    `<span class="trip-name">${escapeHtml(card.title)}</span>` +
    `<span class="trip-meta">${metaChipsHtml(card)}</span>` +
    `</span>` +
    `</button>`;
  const out: string[] = [];
  let year = "";
  for (const card of journeys) {
    if (card.year !== year) {
      year = card.year;
      out.push(`<div class="group-label">${escapeHtml(year)}</div>`);
    }
    out.push(item(card));
  }
  if (drives.length) {
    out.push(`<div class="group-label">Short drives · ${drives.length}</div>`);
    for (const card of drives) out.push(item(card));
  }
  return out.join("");
}

// ── Deep links ──────────────────────────────────────────────────────────────

export type AppRoute =
  | { kind: "home" }
  | { kind: "trip"; id: string }
  | { kind: "watch"; id: string; t: number | null };

/** `#/trip/<id>` · `#/trip/<id>/watch?t=<ms>` · anything else → home. */
export function parseAppRoute(hash: string): AppRoute {
  const raw = String(hash || "").replace(/^#/, "");
  const m = /^\/?trip\/([^/?#]+)(\/watch)?(?:\?(.*))?$/.exec(raw);
  if (!m) return { kind: "home" };
  let id = m[1];
  try {
    id = decodeURIComponent(id);
  } catch {
    /* keep raw */
  }
  if (!m[2]) return { kind: "trip", id };
  const params = new URLSearchParams(m[3] || "");
  const t = params.has("t") ? Number(params.get("t")) : NaN;
  return { kind: "watch", id, t: Number.isFinite(t) && t >= 0 ? Math.round(t) : null };
}

export function formatAppRoute(route: AppRoute): string {
  if (route.kind === "home") return "#/";
  const id = encodeURIComponent(route.id);
  if (route.kind === "trip") return `#/trip/${id}`;
  const t = route.t != null && route.t > 0 ? `?t=${Math.round(route.t)}` : "";
  return `#/trip/${id}/watch${t}`;
}
