/**
 * PlaybackEngine — owns the clock, the compiled timeline and the frame loop.
 *
 * Each animation frame:
 *   1. governor.sample(readiness, frame time) → rate multiplier
 *   2. rate = speed × PLAYBACK_SPEED_REF × pace(last position) × governor
 *   3. clock.advance(wallDt × rate)  (skipped while holding for first paint)
 *   4. host.onFrame(positionAt(clock.timeMs), info)
 *
 * The host (diary-app today, the new UI in Phase 3) draws markers, trail,
 * camera and chrome from the position — it never touches the clock directly.
 */

import { BufferGovernor, type GovernorOptions } from "./buffer-governor";
import { PlaybackClock } from "./clock";
import { groundSpeedMps } from "./flight-plan";
import { clampSpeed, paceMultiplier, timelineRate } from "./pacing";
import { compileTimeline, positionAt } from "./timeline";
import type { PlaybackPosition, RawPlayback, Timeline } from "./types";

export interface FrameInfo {
  /** Wall ms consumed by this frame (clamped). */
  wallDt: number;
  /** Timeline ms per wall ms actually applied. */
  rate: number;
  pace: number;
  governor: number;
  buffering: boolean;
  holding: boolean;
  /** On-screen speed of the car, m/s. */
  groundSpeedMps: number;
  ended: boolean;
  /** Engine compute time before the host callback, ms. */
  engineMs: number;
}

export interface EngineHost {
  /** Basemap readiness for the governor: boolean, or `null` when there is no signal. */
  readiness?: () => boolean | null;
  onFrame: (pos: PlaybackPosition, info: FrameInfo) => void;
  onEnded?: () => void;
  onBuffering?: (buffering: boolean) => void;
  onHold?: (holding: boolean) => void;
  raf?: (cb: (ts: number) => void) => number;
  caf?: (id: number) => void;
  now?: () => number;
  governor?: GovernorOptions;
}

export interface EnginePerf {
  frames: number;
  engineMsAvg: number;
  engineMsMax: number;
  frameMsAvg: number;
  frameMsMax: number;
  /** Wall ms the clock actually credited (after the per-frame gap clamp). */
  wallMsTotal: number;
  /** Timeline ms advanced by the loop since the last reset (excludes seeks). */
  timelineMsTotal: number;
  lastRate: number;
  lastGovernor: number;
  bufferingEvents: number;
}

export class PlaybackEngine {
  readonly clock = new PlaybackClock();
  readonly governor: BufferGovernor;
  timeline: Timeline | null = null;
  speed = 1;
  highlightReel = false;
  playing = false;
  holding = false;
  private rafId: number | null = null;
  private holdToken = 0;
  private lastPos: PlaybackPosition | null = null;
  private readonly cache = new WeakMap<RawPlayback, Timeline>();
  private readonly raf: (cb: (ts: number) => void) => number;
  private readonly caf: (id: number) => void;
  private readonly now: () => number;
  private perfState = PlaybackEngine.freshPerf();

  private static freshPerf() {
    return { frames: 0, engineTotal: 0, engineMax: 0, frameTotal: 0, frameMax: 0, wallTotal: 0, timelineTotal: 0, lastRate: 0, bufferingEvents: 0 };
  }

  constructor(private host: EngineHost) {
    this.governor = new BufferGovernor(host.governor);
    this.raf = host.raf ?? ((cb) => requestAnimationFrame(cb));
    this.caf = host.caf ?? ((id) => cancelAnimationFrame(id));
    this.now = host.now ?? (() => performance.now());
    this.governor.onBuffering((on) => {
      if (on) this.perfState.bufferingEvents += 1;
      this.host.onBuffering?.(on);
    });
  }

  // ── Timeline ─────────────────────────────────────────────────────────────

  /** Compile (memoised) and make this playback the active timeline. Keeps the clock time when possible. */
  load(playback: RawPlayback | null | undefined): Timeline | null {
    if (!playback) {
      this.timeline = null;
      this.clock.setTotal(0);
      this.lastPos = null;
      return null;
    }
    let tl = this.cache.get(playback);
    if (!tl) {
      tl = compileTimeline(playback);
      this.cache.set(playback, tl);
    }
    if (this.timeline !== tl) {
      this.timeline = tl;
      this.clock.setTotal(tl.totalMs);
      this.lastPos = null;
    }
    return tl;
  }

  /** Compile without activating (prefetch / chapters for a card). */
  compile(playback: RawPlayback): Timeline {
    let tl = this.cache.get(playback);
    if (!tl) {
      tl = compileTimeline(playback);
      this.cache.set(playback, tl);
    }
    return tl;
  }

  get timeMs(): number {
    return this.clock.timeMs;
  }

  get totalMs(): number {
    return this.clock.totalMs;
  }

  get progress(): number {
    return this.clock.progress();
  }

  get buffering(): boolean {
    return this.governor.buffering;
  }

  positionAt(ms: number): PlaybackPosition | null {
    return this.timeline ? positionAt(this.timeline, ms) : null;
  }

  position(): PlaybackPosition | null {
    return this.positionAt(this.clock.timeMs);
  }

  // ── Transport ────────────────────────────────────────────────────────────

  /** Move the cursor without emitting a frame. */
  setTime(ms: number): void {
    this.clock.seek(ms);
    this.lastPos = null;
  }

  /** Move the cursor and emit one frame (paused-state redraw). */
  seek(ms: number): PlaybackPosition | null {
    this.setTime(ms);
    return this.emitFrame();
  }

  setSpeed(v: number): number {
    this.speed = clampSpeed(v);
    return this.speed;
  }

  play(): boolean {
    if (!this.timeline || this.timeline.totalMs <= 0) return false;
    if (this.playing) return true;
    this.playing = true;
    this.clock.resetTiming();
    this.governor.reset();
    this.scheduleFrame();
    return true;
  }

  pause(): void {
    this.playing = false;
    this.cancelHold();
    this.clock.resetTiming();
    // A paused frame is not "catching up": drop the buffering flag with the EMAs.
    this.governor.reset();
    if (this.rafId != null) {
      this.caf(this.rafId);
      this.rafId = null;
    }
  }

  /**
   * Freeze the clock until `until` settles or `timeoutMs` passes (first-paint
   * steady gate on Photorealistic 3D). The loop keeps running so the host can
   * show a veil; only time stands still.
   */
  hold(until: Promise<unknown>, timeoutMs = 3500): void {
    const token = ++this.holdToken;
    this.setHolding(true);
    let done = false;
    const finish = () => {
      if (done || token !== this.holdToken) return;
      done = true;
      clearTimeout(timer);
      this.setHolding(false);
      this.clock.resetTiming();
    };
    const timer = setTimeout(finish, timeoutMs);
    until.then(finish, finish);
  }

  cancelHold(): void {
    this.holdToken += 1;
    this.setHolding(false);
  }

  /** Recompute and deliver the current frame without advancing time (redraw after geometry lands, seek, resize). */
  emitFrame(): PlaybackPosition | null {
    const tl = this.timeline;
    if (!tl) return null;
    const pos = positionAt(tl, this.clock.timeMs);
    if (!pos) return null;
    this.lastPos = pos;
    this.host.onFrame(pos, {
      wallDt: 0,
      rate: 0,
      pace: 1,
      governor: this.governor.multiplier,
      buffering: this.governor.buffering,
      holding: this.holding,
      groundSpeedMps: 0,
      ended: this.clock.atEnd(),
      engineMs: 0,
    });
    return pos;
  }

  perf(): EnginePerf {
    const p = this.perfState;
    const n = Math.max(1, p.frames);
    return {
      frames: p.frames,
      engineMsAvg: p.engineTotal / n,
      engineMsMax: p.engineMax,
      frameMsAvg: p.frameTotal / n,
      frameMsMax: p.frameMax,
      wallMsTotal: p.wallTotal,
      timelineMsTotal: p.timelineTotal,
      lastRate: p.lastRate,
      lastGovernor: this.governor.multiplier,
      bufferingEvents: p.bufferingEvents,
    };
  }

  resetPerf(): void {
    this.perfState = PlaybackEngine.freshPerf();
  }

  // ── Loop ─────────────────────────────────────────────────────────────────

  private setHolding(on: boolean): void {
    if (this.holding === on) return;
    this.holding = on;
    this.host.onHold?.(on);
  }

  private scheduleFrame(): void {
    if (this.rafId != null) return;
    this.rafId = this.raf(this.frame);
  }

  /** Drive one frame manually (tests / recording). */
  step(ts: number): void {
    this.frame(ts);
  }

  private readonly frame = (ts: number): void => {
    this.rafId = null;
    const tl = this.timeline;
    if (!this.playing || !tl) return;
    const t0 = this.now();
    const wallDt = this.clock.wallDelta(ts);
    const ready = this.host.readiness ? this.host.readiness() : null;
    const governor = this.governor.sample({ ready, frameMs: wallDt, now: ts });
    let rate = 0;
    let pace = 1;
    let advanced = 0;
    if (!this.holding && wallDt > 0) {
      const basis = this.lastPos ?? positionAt(tl, this.clock.timeMs);
      pace = paceMultiplier(basis, { highlightReel: this.highlightReel });
      rate = timelineRate(this.speed, pace, governor);
      const before = this.clock.timeMs;
      this.clock.advance(wallDt * rate);
      advanced = this.clock.timeMs - before;
    }
    const pos = positionAt(tl, this.clock.timeMs);
    if (!pos) {
      this.playing = false;
      return;
    }
    this.lastPos = pos;
    const ended = this.clock.atEnd();
    const engineMs = this.now() - t0;
    const info: FrameInfo = {
      wallDt,
      rate,
      pace,
      governor,
      buffering: this.governor.buffering,
      holding: this.holding,
      groundSpeedMps: groundSpeedMps(pos, rate),
      ended,
      engineMs,
    };
    this.host.onFrame(pos, info);
    const frameMs = this.now() - t0;
    const p = this.perfState;
    p.frames += 1;
    p.engineTotal += engineMs;
    p.engineMax = Math.max(p.engineMax, engineMs);
    p.frameTotal += frameMs;
    p.frameMax = Math.max(p.frameMax, frameMs);
    p.wallTotal += wallDt;
    p.timelineTotal += advanced;
    p.lastRate = rate;
    if (ended) {
      this.playing = false;
      this.cancelHold();
      this.clock.resetTiming();
      this.host.onEnded?.();
      return;
    }
    if (this.playing) this.scheduleFrame();
  };
}
