import type { SiteData } from "./types";
import { filterJourneyTrips, isJourneyTrip } from "./journey-filter";
import { renderJourneyList, renderShelf, shelfCards } from "./ui/journeys";

function fmt(n: number): string {
  return n.toLocaleString();
}

/** Thumb refs are CDN-absolute after `applyMediaCdn`; local builds keep relative `photos/…`. */
export function thumbUrl(thumb: string): string {
  if (!thumb) return "";
  if (thumb.startsWith("http") || thumb.startsWith("data:")) return thumb;
  return thumb.replace(/^\//, "");
}

/**
 * Static chrome that only depends on the index: counts, the Home shelf and the
 * Journeys sheet list. The legacy runtime wires clicks / hover afterwards.
 */
export function hydrateShell(data: SiteData): void {
  const { dashboard, trips } = data;
  const journeyTrips = filterJourneyTrips(trips);
  const setText = (id: string, text: string) => {
    const el = document.getElementById(id);
    if (el) el.textContent = text;
  };

  setText("stat-trip-count", String(journeyTrips.length));
  setText("panel-trip-count", String(journeyTrips.length));
  setText("journey-shelf-count", String(journeyTrips.length));

  const splash = document.querySelector("#splash p");
  if (splash) {
    splash.textContent = `Miles become memories · ${journeyTrips.length} journeys · ${fmt(dashboard.total_miles)} miles`;
  }

  const panelSub = document.getElementById("panel-sub");
  if (panelSub) {
    panelSub.textContent = `${journeyTrips.length} journeys · ${trips.length - journeyTrips.length} short drives · ${fmt(dashboard.total_miles)} miles`;
  }

  const allMeta = document.querySelector('.trip-item[data-id="all"] .trip-meta');
  if (allMeta) {
    allMeta.textContent = `${trips.length} trips · ${fmt(dashboard.total_miles)} mi`;
  }

  const listMount = document.getElementById("trip-list-items");
  if (listMount) listMount.innerHTML = renderJourneyList(trips, thumbUrl);

  const shelfMount = document.getElementById("journey-shelf-track");
  if (shelfMount) shelfMount.innerHTML = renderShelf(trips, thumbUrl);

  // Expose for legacy runtime checks (map keeps all trips; UI lists journeys only).
  window.__MMD_JOURNEY_TRIP_IDS = new Set(journeyTrips.map((trip) => trip.id));
  window.__MMD_IS_JOURNEY_TRIP = isJourneyTrip;
  window.__MMD_SHELF_ORDER = shelfCards(trips).map((card) => card.id);
}
